CREATE TEMPORARY VIEW dwm_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_ids
    ,array_intersect(scenario_tags,
        array(
            'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
            'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
            'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
            'DA_Daily Discover', 'DA_You May Also Like'
        )
    ) AS scenario_tags
    ,array_intersect(source1_scenario_tags,
        array(
            'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
            'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
            'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
            'DA_Daily Discover', 'DA_You May Also Like'
        )
    ) AS source1_scenario_tags
    ,array_intersect(source2_scenario_tags,
        array(
            'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
            'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
            'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
            'DA_Daily Discover', 'DA_You May Also Like'
        )
    ) AS source2_scenario_tags
    ,item_id
    ,split(queues, ',')[0] AS queue -- '' and null remain the same
    ,split(source1_queues, ',')[0] AS source1_queue
    ,split(source2_queues, ',')[0] AS source2_queue
    ,cast(coalesce(is_ads, false) as string) as is_ads
    ,imp_cnt
    ,click_cnt
    ,if(is_back = false, ppv_cnt, 0) as ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,avg_imp_price_local / exchange_rate as avg_imp_price_usd
FROM
    srdi_mart.dwm_sr_data_warehouse_platform_user_item
LEFT JOIN
    fx_rate_${grass_region_without_quote}
WHERE
    grass_region IN (${grass_region})
    AND local_date = ${local_date}
    AND operation IN ('impression', 'click', 'ppv', 'cart', 'order')
    AND size(exp_group_ids) > 0
    AND (
        (coalesce(queues, '') != '' and size(array_intersect(scenario_tags,
            array(
                'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
                'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
                'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
                'DA_Daily Discover', 'DA_You May Also Like'
            )
        )) > 0)
        or (coalesce(source1_queues, '') != '' and size(array_intersect(source1_scenario_tags,
            array(
                'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
                'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
                'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
                'DA_Daily Discover', 'DA_You May Also Like'
            )
        )) > 0)
        or (coalesce(source2_queues, '') != '' and size(array_intersect(source2_scenario_tags,
            array(
                'DA_Cart_Unify', 'DA_Buy Again (Me Page)',
                'DA_Cart Recommendation', 'DA_mpp_ymal-order_list',
                'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
                'DA_Daily Discover', 'DA_You May Also Like'
            )
        )) > 0)
    )
;

