CREATE TEMPORARY VIEW dwm_explode_tag_${grass_region_without_quote} AS
SELECT 
    user_id
    ,exp_group_id
    ,scenario_tag
    ,queue
    ,is_ads
    ,source_level
    ,sum(imp_cnt) AS imp_cnt
    ,sum(click_cnt) AS click_cnt
    ,sum(ppv_cnt) AS ppv_cnt
    ,sum(cart_cnt) AS cart_cnt
    ,sum(order_cnt) AS order_cnt
    ,sum(gmv) AS gmv
    ,sum(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,sum(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,sum(atc_same_day_gmv) AS atc_same_day_gmv
    ,sum(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,sum(avg_imp_price_usd * imp_cnt) / sum(if(avg_imp_price_usd is null, 0, imp_cnt)) as avg_imp_price_usd
FROM
    dwm_filter_table_${grass_region_without_quote} 
    LATERAL VIEW EXPLODE(scenario_tags) AS scenario_tag
GROUP BY GROUPING SETS (
    -- source_level = 0/1/2; is_ads = __ALL__
    (user_id, exp_group_id, scenario_tag, queue, source_level)
    -- source_level = __ALL__; is_ads = true/false
    ,(user_id, exp_group_id, scenario_tag, queue, is_ads)
    -- source_level = __ALL__; is_ads = __ALL__
    ,(user_id, exp_group_id, scenario_tag, queue)
);

