CREATE TEMPORARY VIEW dwm_raw_user_exp_${grass_region_without_quote} AS
SELECT
    t1.user_id
    ,t2.exp_group_id
    ,scenario_tags
    ,item_id
    ,queue
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
