    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,avg_imp_price_local
FROM
    dwm_raw_${grass_region_without_quote} as t1
INNER JOIN
    user_exp_${grass_region_without_quote} as t2
    -- new_arrival users should be a small subset only, so inner join before aggregation
ON
    t1.user_id = t2.user_id
;

