    ,sum(IF(imp_cnt > 0, 1, NULL)) AS imp_uu
    ,sum(IF(click_cnt > 0, 1, NULL)) AS click_uu
    ,sum(IF(ppv_cnt > 0, 1, NULL)) AS ppv_uu
    ,sum(IF(cart_cnt > 0, 1, NULL)) AS cart_uu
    ,sum(IF(order_cnt > 0, 1, NULL)) AS order_uu
    ,sum(imp_cnt) AS imp_cnt
    ,sum(click_cnt) AS click_cnt
    ,sum(ppv_cnt) AS ppv_cnt
    ,sum(cart_cnt) AS cart_cnt
    ,sum(order_cnt) AS order_cnt
    ,sum(gmv) AS gmv
    ,sum(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,sum(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,sum(atc_same_day_gmv) AS atc_same_day_gmv
    ,sum(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,sum(avg_imp_price_usd * imp_cnt) / sum(if(avg_imp_price_usd is null, 0, imp_cnt)) as avg_imp_price_usd
FROM
    dwm_explode_tag_${grass_region_without_quote}
GROUP BY
    exp_group_id
    ,scenario_tag
    ,queue;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_exp_queue_level_metrics_1d
PARTITION 
(
    grass_region = ${grass_region}, 
    local_date = ${local_date},
    exp_type = 'assign_log_join'
)
SELECT
    exp_group_id
    ,queue
    ,scenario_tag
    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,avg_imp_price_usd
    ,'__ALL__' as is_ads
    ,0 as source_level
FROM
    res_data_${grass_region_without_quote}
